cmd:
set -e
export LC_ALL=C.UTF-8
cd /root/Iryna_Karmazina && git fetch -q origin claude/direct-automation-expeditor-671esy
B=origin/claude/direct-automation-expeditor-671esy
cp /root/deals_trigger.py /root/deals_trigger.py.bak-sync0730
git show $B:direct_sync/deals_trigger.py > /root/deals_trigger.py
git show $B:direct_sync/expeditor-direct-sync.timer > /etc/systemd/system/expeditor-direct-sync.timer
git show $B:direct_sync/maersk-track-sync.timer > /etc/systemd/system/maersk-track-sync.timer
systemctl daemon-reload
systemctl restart expeditor-direct-sync.timer maersk-track-sync.timer deals-sync-trigger.service
cp /root/unitex-os-www/index.html /root/unitex-os-www/index.html.bak-syncbtn
python3 - <<'PY'
p='/root/unitex-os-www/index.html'; s=open(p,encoding='utf-8').read()
if 'MAERSK_OK tracked' in s: print("UI_ALREADY_OK")
else:
    old='''    sb.disabled=true; sb.textContent="⏳ Оновлюю…";
    try{
      const r = await fetch("/sync"); const js = await r.json();
      const m = /new=(\\d+)/.exec(js.result||"");
      toast(m && m[1]!=="0" ? `✅ Додано нових угод: ${m[1]}` : "✅ Синхронізовано, нових угод немає");'''
    new='''    sb.disabled=true; sb.textContent="⏳ Оновлюю… (до 2 хв: Експедитор + трекінг)";
    try{
      const r = await fetch("/sync"); const js = await r.json();
      const res = js.result||"";
      const m = /new=(\\d+)/.exec(res);
      const t = /MAERSK_OK tracked=(\\d+) updated=(\\d+)/.exec(res);
      const parts = [m && m[1]!=="0" ? `додано нових угод: ${m[1]}` : "нових угод немає"];
      if (t) parts.push(`трекінг Maersk: оновлено ${t[2]} з ${t[1]}`);
      toast("✅ " + parts.join(" · "));'''
    assert old in s, "блок кнопки не знайдено"
    open(p,'w',encoding='utf-8').write(s.replace(old,new,1)); print("UI_PATCHED")
PY
echo "ТАЙМЕРИ:"; systemctl list-timers --no-pager | grep -E 'expeditor-direct|maersk-track' | sed 's/  */ /g' | cut -d' ' -f1-4
T=$(cat /root/deals-sync-trigger-token)
nohup sh -c "curl -s --max-time 900 'http://127.0.0.1:8788/run?token=$T' > /root/direct-sync/button_test.json" >/dev/null 2>&1 &
echo "тест кнопки запущено"
